213:         public static void SaveVisionImage(Bitmap bitmap, List<string> filePath,string bitmapName)
214:         {
215:             try
216:             {
217:                 string allPath = "";
218: 
219:                 // 创建文件夹
220:                 foreach (string path in filePath)
221:                 {
222:                     if (path == string.Empty)
223:                     {
224:                         continue;
225:                     }
226: 
227:                     allPath = Path.Combine(allPath, path);
228:                     if (!Directory.Exists(allPath))
229:                     {
230:                         Directory.CreateDirectory(allPath);
231:                     }
232:                 }
233: 
234:                 // 非法字符剔除
235:                 foreach (char rInvalidChar in System.IO.Path.GetInvalidPathChars())
236:                 {
237:                     if (allPath.Contains(rInvalidChar.ToString()))
238:                     {
239:                         allPath = allPath.Replace(rInvalidChar.ToString(), string.Empty);
240:                     }
241:                 }
242: 
243:                 // 考虑磁盘是否够用
244:                 BitmapBlockingCollection.Add(((Bitmap)bitmap, allPath + "//" + bitmapName));
245:             }
246:             catch (Exception ex)
247:             {
248:                 LogHelper.Post(Level.Error, $"流程运行故障！", ex, LogCategory.PR);
249:             }
250:         }

