135:         private void BackgroundWorkerDoWork()
136:         {
137:             CommonUtil.SetCurrentThreadName("定位失败实时显示线程");
138: 
139:             try
140:             {
141:                 while (!this.isclose)
142:                 {
143:                     if (this.isAllowWork)
144:                     {
145:                         this.isWork = true;
146: 
147:                         if (this.entity == null)
148:                         {
149:                             AKRSCamera aKRSCamera = HardwareRepositoryService.GetHardware<AKRSCamera>(this.PRHardware.CameraName);
150:                             Bitmap bitmap = aKRSCamera.SnapShot(false, SnapImageFormat.Format8bppIndexed);
151: 
152:                             this.BeginInvoke(() =>
153:                             {
154:                                 this.pictureEdit1.Image?.Dispose();
155:                                 this.pictureEdit1.Image = bitmap;
156:                             });
157:                         }
158:                         else
159:                         {
160:                             if (this.PRHardware != null)
161:                             {
162:                                 lock (this.entity)
163:                                 {
164:                                     this.entity.DoWork(PRHardware, false, false);
165:                                     this.BitmapShow();
166:                                 }
167:                             }
168:                             else
169:                             {
170:                                 this.entity.DoWork(PRHardware, false, false);
171:                                 this.BitmapShow();
172:                             }
173:                         }
174: 
175:                         this.isWork = false;
176:                     }
177: 
178:                     Thread.Sleep(300);
179:                 }
180:             }
181:             catch (Exception ex)
182:             {
183:                 throw new Exception("定位失败实时显示线程异常" + ex.Message);
184:             }
185:         }

339:         private void BtOK_Click(object sender, EventArgs e)
340:         {
341:             this.isAllowWork = false;
342: 
343:             // 如果正在工作则等待工作完成
344:             while (this.isWork)
345:             {
346:                 Thread.Sleep(100);
347:             }
348: 
349:             // 如果没有PR实体直接返回成功
350:             if (this.entity == null)
351:             {
352:                 this.DialogResult = DialogResult.OK;
353:                 return;
354:             }
355: 
356:             // 双模板跳过
357:             if (this.entity.Alg.AlgFlowType == AlgFlowTypeEnum.SymmetricModeleAlg || this.caption == "晶圆线程")
358:             {
359:                 this.DialogResult = DialogResult.OK;
360:                 return;
361:             }
362: 
363:             // 胶量检测之后返回结果，点胶OK就是认为可以
364:             if (this.entity.Alg.AlgFlowType == AlgFlowTypeEnum.EpoxyDetectAlg)
365:             {
366:                 this.DialogResult = DialogResult.OK;
367:                 return;
368:             }
369: 
370:             lock (this.entity)
371:             {
372:                 ExcuteResult result = this.entity.DoWork(this.PRHardware,false, true);
373: 
374:                 if (result != ExcuteResult.Success)
375:                 {
376:                     AKRSXtraMessageBox.Show("没有找到模板，请重试");
377:                     this.isAllowWork = true;
378:                 }
379:                 else
380:                 {
381:                     if (this.entity.AlgResult is MatchResult match)
382:                     {
383:                         this.BaseAlgResult = new MatchResult(match.CenterX, match.CenterY, match.Angle);
384:                     }
385:                     else
386:                     {
387:                         this.BaseAlgResult = this.entity.AlgResult;
388:                     }
389: 
390: 
391:                     //// 保存结果图片
392:                     //Bitmap bitmap = this.entity.AlgResult.OutPutImg1;
393:                     //string path = "D:\\VisionBitmapData\\" + DateTime.Now.ToString("ddhhmmssfff") + this.entity.GetName() + ".bmp";
394: 
395:                     this.DialogResult = DialogResult.OK;
396: 
397:                     // 如果是胶量检测则提示
398:                     if (this.entity.Alg.AlgFlowType == AlgFlowTypeEnum.EpoxyDetectAlg)
399:                     {
400:                         DialogResult dialogResult = AKRSXtraMessageBox.Show("是否暂停设备", "提示", MessageBoxButtons.OKCancel);
401:                         if (dialogResult == DialogResult.OK)
402:                         {
403:                             Machine.GetInstance().Pause();
404:                         }
405:                     }
406:                 }
407:             }
408:         }

