305:         /// </summary>
306:         /// <param name="name">当前需要示教的名称</param>
307:         /// <returns>结果</returns>
308:         public bool IsNormalOrderAssistant(string name)
309:         {
310:             if (this.IsAssistantSucceed)
311:             {
312:                 return true;
313:             }
314: 
315:             List<AssistantState> list = this.GetAssistantStates();
316: 
317:             AssistantState assistantState = list.Find(it => it.ChName == name);
318: 
319:             int index = list.IndexOf(assistantState);
320: 
321:             for (int i = 0; i < index; i++)
322:             {
323:                 if (list[i].State == AssistantStateEnum.UnAble)
324:                 {
325:                     AKRSXtraMessageBox.Show($"请先完成步骤：{list[i].ChName}");
326:                     return false;
327:                 }
328:             }
329: 
330:             return true;
331:         }

